def transform(grid):
    h = len(grid)
    if h == 0:
        return []
    rows = []
    for tile_y in range(3):
        indices = range(h - 1, -1, -1) if tile_y % 2 == 0 else range(h)
        for i in indices:
            row = grid[i]
            rows.append(list(reversed(row)) + list(row))
    return rows

